import json,html,pathlib,shutil
root=pathlib.Path(__file__).resolve().parent.parent
out=root/'public/presentasi-mahasiswa'
packages=json.load(open(root/'output/presentasi-mahasiswa/catalog-2026-10-21.json'))['packages']; by={p['package_id']:p for p in packages}
slides=[]
def add(title,body,notes,theme='',source=''):
 slides.append(dict(title=title,body=body,notes=notes,theme=theme,source=source))
def label(s):return f'<div class="eyebrow">{s}</div>'
def head(s):return f'<h1>{s}</h1>'
def para(s):return f'<p class="lead">{s}</p>'
def rows(items):return '<div class="rows">'+''.join(f'<div class="row"><b>{a}</b><span>{b}</span></div>' for a,b in items)+'</div>'
def prompt(s):return '<div class="prompt"><span>Contoh prompt · siap dicoba</span><p>'+s+'</p></div>'
def price(p):return 'Rp'+f"{p['terms']['price_idr']:,}".replace(',','.')
def quota(p):return '1 miliar' if p['grant_tokens']==10**9 else str(p['grant_tokens']//10**6)+' juta'
def catalog(ids):
 ps=[by[x] for x in ids]
 return '<table><thead><tr><th>Paket & akses model</th><th>Kuota token</th><th>Berlaku</th><th>Harga paket</th></tr></thead><tbody>'+''.join(f'<tr data-package="{p["package_id"]}"><td><b>{html.escape(p["name"])}</b><small>{html.escape(" · ".join(p["model_ids"]))}</small></td><td>{quota(p)}</td><td>{p["terms"]["validity_days"]} hari</td><td class="money">{price(p)}</td></tr>' for p in ps)+'</tbody></table><p class="fine">Belum termasuk biaya layanan checkout. Akses mengikuti paket, akun, dan API key. Kuota bundling mengikuti ketentuan layanan.</p>'
add('Deadline besok. Skill kamu sampai mana?',label('TokenGateway / Campus Session')+head('Deadline besok.<br><em>Skill kamu</em><br>sampai mana?')+para('AI bisa bantu ngerjain. Kamu tetap perlu paham yang dikerjain.')+'<div class="cover-stamp"><b>Belajar.<br>Bangun.<br>Buktiin.</b><span>AI untuk mahasiswa<br>21 Oktober 2026</span></div>', 'Buka dengan angkat tangan: siapa yang pernah buka AI saat deadline? Jeda, biarkan mereka merespons. Sampaikan sesi ini tentang menghasilkan karya yang bisa dijelaskan, bukan sekadar jawaban. Durasi deck sekitar 25–35 menit, katalog bisa dibuka cepat lalu jadi bahan Q&A.','cover')
add('Quick check: kamu tim yang mana?',label('Mulai dari pengalaman kamu')+head('Kamu tim<br><em>yang mana?</em>')+'<div class="poll"><div><span>A</span><h2>Baru buka AI<br>pas panik.</h2></div><div><span>B</span><h2>Sering pakai.<br>Masih copy-paste.</h2></div><div><span>C</span><h2>Sudah bikin<br>sesuatu sendiri.</h2></div></div>'+para('Angkat tangan. Semua boleh mulai dari titik yang berbeda.'),'Ajak audiens memilih A, B, atau C. Jangan mengejek jawaban. Hubungkan respons ke tiga tujuan sesi: memberi instruksi, mengecek hasil, membuat proyek.')
add('Data industri 2026', '', 'Bagian data industri diisi dari campus_content.enrich dengan sumber 2026.')
add('Dari tugas kampus ke skill kerja',label('Yang bisa kamu mulai minggu ini')+head('Tugas kampus.<br><em>Latihan skill kerja.</em>')+rows([('Anak tech','Bikin fitur, baca error, tulis test, review kode.'),('Anak data','Rapikan CSV, susun analisis, cek angka, jelaskan temuan.'),('Anak bisnis / komunikasi','Susun hipotesis, bedah feedback, bikin draft presentasi.'),('Semua jurusan','Minta penjelasan, latihan tanya jawab, cek pemahaman.')]),'Tekankan mahasiswa nonteknis tetap punya pintu masuk. Ini contoh aktivitas belajar dengan AI secara umum; tidak semua fitur aplikasi konsumen tersedia di gateway API.')
add('Bisa prompt itu baru awal',label('Cara pakai AI dengan baik')+head('Bisa prompt<br>itu <em>baru awal.</em>')+'<div class="ladder"><div><span>01</span><h2>Kasih konteks</h2><p>Tujuan, bahan, batasan, dan format hasil.</p></div><div><span>02</span><h2>Periksa hasil</h2><p>Uji kode, hitung ulang, buka sumber aslinya.</p></div><div><span>03</span><h2>Jelaskan balik</h2><p>Kalau belum bisa menjelaskan, lanjut belajar.</p></div><div><span>04</span><h2>Perbaiki</h2><p>Kasih feedback spesifik, lalu bandingkan.</p></div></div>','Gunakan contoh sederhana: minta AI menjelaskan fungsi yang baru dibuat. Tanyakan kenapa memilih pendekatan itu dan apa kelemahannya.')
add('Prompt yang bisa langsung kamu pakai',label('Simpan pola ini')+head('Tujuan + konteks + batasan<br>+ <em>bentuk hasil.</em>')+prompt('Saya mahasiswa semester 3, sedang belajar Python. Bantu analisis CSV pengeluaran dummy dengan kolom tanggal, kategori, dan nominal. Jangan mengarang data kosong. Berikan kode pandas, cara mengecek total, lalu jelaskan hasil dengan bahasa sederhana.')+'<div class="underlines"><span>Tujuan jelas</span><span>Input spesifik</span><span>Ada cara validasi</span></div>','Bedah prompt satu per satu. Beri audiens 30 detik untuk mengubahnya sesuai jurusan. Tidak ada formula prompt yang menjamin jawaban benar.','light')
add('Coding: dari ide ke fitur yang jalan',label('Praktik 01 / Development')+head('“Bikinin aplikasi”<br>masih <em>terlalu luas.</em>')+'<div class="two"><div>'+rows([('Brief','Aplikasi kas organisasi: tambah pengeluaran dan lihat total.'),('Bangun','Pecah menjadi data, form, validasi, dan ringkasan.'),('Uji','Nominal negatif ditolak. Total cocok dengan transaksi.'),('Review','Minta penjelasan fungsi, celah keamanan, dan trade-off.')])+'</div>'+prompt('Bantu rancang fitur tambah pengeluaran. Pakai React + TypeScript. Simpan lokal untuk latihan. Sebelum menulis kode, jelaskan struktur data dan 4 kasus uji. Jangan tambahkan login dulu.')+'</div>','Ini skenario latihan, bukan klaim demo produk yang sudah dijalankan. Tekankan jangan menyuruh agent mengubah seluruh repo sekaligus. Baca diff dan jalankan tes. Proyek kas di sini tidak dipakai untuk transaksi uang nyata.')
add('Data: angka cantik belum tentu benar',label('Praktik 02 / Analisis data')+head('Angkanya rapi.<br><em>Sudah dicek?</em>')+'<div class="two"><div class="sheet"><span>Data ilustrasi · pengeluaran organisasi</span><div><b>Kategori</b><b>Nominal</b></div><div><span>Konsumsi</span><span>Rp450.000</span></div><div><span>Transportasi</span><span>Rp200.000</span></div><div><span>Perlengkapan</span><span>Rp350.000</span></div><div class="total"><b>Total</b><b>Rp1.000.000</b></div><div class="bar"><i></i></div><small>Konsumsi = 45% dari total contoh</small></div><div>'+rows([('Minta AI bantu','Tulis kode untuk cek data kosong, duplikat, dan total.'),('Hitung ulang','450.000 ÷ 1.000.000 = 45%. Cocokkan ke data mentah.'),('Baca batasnya','Sampel kecil belum cukup untuk menyimpulkan kebiasaan semua mahasiswa.')])+'</div></div>','Angka di slide sengaja data dummy yang diberi label, bukan data pelanggan. Total 1 juta dan proporsi 45% diverifikasi secara aritmetika. Gunakan Python/pandas atau spreadsheet sebagai tempat eksekusi; API tidak otomatis menjalankan analisis file.')
add('Pakai AI, tetap pegang tanggung jawab',label('Skill yang sering kelewat')+head('AI bisa salah.<br><em>Kamu yang cek.</em>')+rows([('Sumber','Buka artikel atau paper aslinya. Cek penulis, tanggal, dan relevansi.'),('Data pribadi','Pakai data dummy atau anonim. Simpan API key di server.'),('Tugas kuliah','Ikuti aturan dosen. Jelaskan penggunaan AI bila diminta.'),('Kode & angka','Jalankan test dan cek rumus. Jangan percaya hasil hanya karena terdengar yakin.')]),'Jadikan ini kebiasaan kerja praktis. Contoh: AI bisa mengarang judul jurnal. Jangan mengumpulkan karya yang tidak bisa dipertanggungjawabkan.')
add('Eksplorasi AI jangan bikin dompet panik',label('Biaya juga perlu masuk hitungan')+head('Mau eksplorasi AI.<br><em>Dompet ikut mikir.</em>')+'<div class="subscription"><div><span>Claude Pro</span><b>US$20<small>/ bulan</small></b></div><div><span>ChatGPT Plus</span><b>US$20<small>/ bulan</small></b></div><div><span>Google AI Pro</span><b>US$19,99<small>/ bulan</small></b></div></div>'+para('Buat budget mahasiswa, langganan beberapa aplikasi sekaligus bisa terasa berat.')+'<p class="fine">Harga referensi AS, bulanan reguler; pajak, wilayah, promo, dan penawaran mahasiswa dapat berbeda. Ada opsi gratis. Ini langganan aplikasi, dengan fitur berbeda dari paket API TokenGateway.</p>','Perbandingan adalah bentuk pengeluaran, bukan kesetaraan fitur atau model. ChatGPT Plus $20, bukan menyebutnya ChatGPT Pro $20. Untuk Pro arahkan ke harga resmi terkini. Google $19.99 adalah referensi AS, bukan tarif Indonesia. Jangan mengeklaim TokenGateway menggantikan fitur voice, storage, video, atau deep research.','', 'Sumber harga: claude.com/pricing · help.openai.com/en/articles/6950777-what-is-chatgpt-plus · one.google.com/about/plans')
add('Kenalan dengan TokenGateway',label('Pintu masuk ke API AI')+head('Bikin proyek AI.<br><em>Mulai dari paket kecil.</em>')+'<div class="gateway"><div class="node">Aplikasi kamu<br><small>Script · backend · coding tool</small></div><strong>TokenGateway<br><small>Satu base URL</small></strong><div class="node">Model sesuai paket<br><small>GLM · DeepSeek · GPT · Gemini · Qwen · Kimi</small></div></div>'+para('Pilih paket → bayar QRIS → buat API key → hubungkan ke aplikasi.')+'<p class="fine">Gateway API dengan kuota dan masa berlaku. Akses model mengikuti paket, akun, dan key. Kompatibilitas format mengikuti dokumentasi.</p>','Jelaskan API seperti cara aplikasi mengirim permintaan ke model. Ini produk untuk dipakai melalui aplikasi atau tool yang kompatibel, bukan paket akun premium aplikasi lain. Nama model mengikuti katalog gateway, bukan sertifikat kemitraan vendor.','', 'TokenGateway · tokengateway.ai.id/docs · katalog publik, diakses 21 Oktober 2026')
p=by['pass-glm-5.3-flash-50m']
add('Mulai dari Rp10.000',label(p['name'])+'<div class="offer"><div>'+head('Mulai dari')+f'<div class="huge">{price(p)}</div><p class="fine">Harga paket. Belum termasuk biaya layanan checkout.</p></div><div class="offer-details"><b>{quota(p)}<small>token</small></b><b>{p["terms"]["validity_days"]} hari<small>masa berlaku</small></b><span>Model: GLM 5.3 Flash<br>Pembayaran: QRIS</span></div></div>'+para('Buat mulai belajar request API dan mencoba proyek kecil.')+'<p class="fine">Kuota token bukan jumlah prompt. Pemakaian nyata bergantung pada input, output, dan aturan layanan.</p>','Jangan menyebut harga total checkout 10 ribu. Kuota 50 juta bukan estimasi berapa hari coding atau jumlah pertanyaan. Ajak lihat rincian paket dan biaya sebelum bayar.','blue','Katalog TokenGateway · pass-glm-5.3-flash-50m · diakses 21 Oktober 2026')
add('Token itu apa sih?',label('Sebelum pilih paket')+head('Token itu<br><em>potongan teks.</em>')+'<div class="tokenline"><span>Jelaskan</span><span> kode</span><span> ini</span><span> secara</span><span> sederhana</span></div><p class="fine">Ilustrasi pemotongan saja. Tokenisasi sebenarnya berbeda menurut model dan bahasa.</p>'+rows([('Input','Instruksi, riwayat chat, dan bahan yang dikirim.'),('Output','Jawaban yang dihasilkan model.'),('Kuota & masa berlaku','Baca dua-duanya. Kuota besar bukan berarti akses tanpa batas waktu.')]),'Perhitungan token cached atau reasoning terhadap grant belum dijelaskan lengkap oleh katalog. Hindari mengonversi 1 token ke jumlah kata yang pasti, atau menghitung berapa prompt bisa dipakai.','light')
add('Satu workflow, banyak pilihan model',label('Pilih berdasarkan tugas')+head('Mulai dari tugasnya.<br><em>Baru pilih modelnya.</em>')+rows([('Eksperimen harian','Cek paket Flash untuk mencoba instruksi dan request awal.'),('Bangun fitur','Cek Coder & Architect atau pass coding yang tersedia.'),('Uraikan masalah','Cek paket reasoning, lalu bandingkan hasil di tugas kamu.'),('Eksplorasi model lain','Cek Gemini, Kimi, atau keluarga GPT sesuai akses paket.')])+'<p class="fine">Arah eksperimen, bukan hasil benchmark. Uji kualitas pada kasus sendiri. Nama dan versi mengikuti label katalog gateway.</p>','Jangan menjanjikan satu model terbaik untuk semua jurusan. Pilih subset kecil, tentukan kriteria, bandingkan jawaban secara terukur. Claude tidak muncul dalam paket publik, jadi jangan ditawarkan sebagai model tersedia.')
add('Paket bundling',label('Katalog 01 / 4 · Bundling')+head('Satu paket.<br><em>Beberapa pilihan model.</em>')+catalog([p['package_id'] for p in packages if p['terms']['category']=='bundling']),'Enam bundling. Jelaskan perbedaan kuota dan masa berlaku. Frontier 20M dan 30M memiliki model IDs sama dengan kuota dan durasi berbeda. Cara pooling kuota mengikuti ketentuan gateway. Tabel nama dan harga diambil dari katalog live.','catalog','Katalog paket TokenGateway · snapshot 21 Oktober 2026')
add('Paket Flash & kuota besar',label('Katalog 02 / 4 · Flash')+head('Mulai kecil.<br><em>Atau eksplorasi lebih jauh.</em>')+catalog(['pass-glm-5.3-flash-50m','pass-glm-5.3-flash-120m','pass-deepseek-flash-150m','pass-glm-5.2-60m','pass-titan-flash-1b']),'Lima pass Flash termasuk Titan satu miliar token, berlaku 30 hari. Jangan janjikan kuota pasti cukup sebulan. Pass DeepSeek Flash 150M mencantumkan dua model IDs; tampilkan keduanya sesuai sumber.','catalog','Katalog paket TokenGateway · snapshot 21 Oktober 2026')
add('Paket coding, reasoning & Gemini',label('Katalog 03 / 4 · Fokus tugas')+head('Buat coding.<br><em>Buat mikir lebih dalam.</em>')+catalog(['pass-qwen3-coder-60m','pass-deepseek-v4-pro-65m','pass-glm-5.3-40m','pass-gemini-3.7-flash-60m','pass-gemini-3.8-flash-50m']),'Lima pass. Tag judul membantu navigasi, bukan benchmark kemampuan atau jaminan hasil. Gemini Flash melalui gateway bukan langganan Google AI Pro.','catalog','Katalog paket TokenGateway · snapshot 21 Oktober 2026')
add('Paket GPT & Kimi',label('Katalog 04 / 4 · GPT & Kimi')+head('Pilihan lain untuk<br><em>proyek berikutnya.</em>')+catalog(['pass-gpt-6-luna-60m','pass-gpt-6-sol-50m','pass-gpt-6.1-sol-25m','pass-gpt-6-astra-15m','pass-kimi-k3-50m']),'Lima pass terakhir. Luna sekarang Rp30.000 di katalog live tanggal 21 Oktober, bukan Rp22.000 di snapshot 12 Oktober studio. Nama model adalah label katalog gateway; tidak menyiratkan upstream vendor sudah terverifikasi.','catalog','Katalog paket TokenGateway · snapshot 21 Oktober 2026')
add('Bingung pilih? Mulai dari satu proyek',label('Cara menentukan paket')+head('Belum perlu<br><em>beli semuanya.</em>')+'<div class="choices"><div><span>Belajar API pertama</span><h2>GLM 5.3 Flash 50M</h2><b>'+price(by['pass-glm-5.3-flash-50m'])+'</b><p>50 juta token · 7 hari</p></div><div><span>Latihan bangun fitur</span><h2>Coder & Architect</h2><b>'+price(by['pkg-coder-architect-50m'])+'</b><p>50 juta token · 14 hari</p></div><div><span>Coba beberapa Flash</span><h2>Kilat All-Star Flash</h2><b>'+price(by['pkg-allstar-flash-100m'])+'</b><p>100 juta token · 10 hari</p></div></div><p class="fine">Contoh pilihan awal, bukan jaminan kecocokan. Harga paket belum termasuk biaya layanan checkout. Detail model ada di katalog sebelumnya.</p>','Bantu peserta memilih sesuai tujuan dan waktu yang benar-benar tersedia. Rekomendasi ini kurasi dari katalog, bukan produk baru atau bundling mahasiswa. Jangan mendorong beli banyak paket bersamaan tanpa memperhatikan masa berlaku.')
add('Dari daftar sampai request pertama',label('Mulainya dari sini')+head('Siapin proyeknya.<br><em>Hubungkan API-nya.</em>')+'<div class="steps"><div><b>01</b><h2>Daftar & verifikasi</h2><p>Buka website dan verifikasi email sebelum membeli.</p></div><div><b>02</b><h2>Pilih & bayar</h2><p>Cek model, kuota, masa berlaku, dan total checkout. Bayar QRIS.</p></div><div><b>03</b><h2>Buat API key</h2><p>Gunakan console. Simpan key di environment server.</p></div><div><b>04</b><h2>Kirim & pantau</h2><p>Pilih model yang diizinkan, coba request, lalu cek usage.</p></div></div><p class="fine">Alur berdasarkan dokumentasi publik. Konfigurasi coding tool mengikuti versi dan dukungan endpoint masing-masing.</p>','Jangan membeli atau menjalankan checkout saat presentasi tanpa kebutuhan. Waktu aktivasi transaksi belum diuji. Tunjukkan docs untuk peserta yang ingin setup tool. Jangan menampilkan API key asli pada layar.','', 'tokengateway.ai.id/pricing · tokengateway.ai.id/docs')
add('Bentuk request pertamamu',label('Contoh / Python · jalankan di server atau lokal')+head('Satu request.<br><em>Awal proyek kamu.</em>')+'<div class="two code-layout"><pre><code>import os\nfrom openai import OpenAI\n\nclient = OpenAI(\n    api_key=os.environ["TOKEN_GATEWAY_API_KEY"],\n    base_url="https://tokengateway.ai.id/v1",\n)\n\nresult = client.chat.completions.create(\n    model="glm-5.3-flash",\n    messages=[{"role": "user", "content":\n        "Jelaskan fungsi Python untuk pemula."}],\n)\nprint(result.choices[0].message.content)</code></pre><div>'+rows([('Persiapan','Install paket openai. Isi environment key di perangkat sendiri.'),('Akses','Model contoh memerlukan paket dan API key yang mengizinkannya.'),('Cek hasil','Baca respons. Pantau usage. Jangan taruh key di frontend.')])+'</div></div>','Contoh format request berdasarkan docs gateway dan pola SDK; bukan demo operasional yang sudah diuji dengan akun berbayar. Jangan klaim hasil aktual. Jika mau live demo, siapkan akun dan key milik presenter sebelumnya.','', 'Dokumentasi gateway · https://tokengateway.ai.id/docs')
add('Challenge: pulang bawa satu karya',label('Giliran kamu / 7 hari latihan')+head('Pulang bawa<br><em>satu karya.</em>')+'<div class="challenge"><div><b>Hari 1</b><p>Pilih satu masalah kampus.</p></div><div><b>Hari 2–3</b><p>Bikin versi paling sederhana.</p></div><div><b>Hari 4–5</b><p>Uji kode atau cek angka.</p></div><div><b>Hari 6–7</b><p>Demo dan jelaskan prosesnya.</p></div></div>'+para('Pilih: kas organisasi · dashboard pengeluaran dummy · kuis materi kuliah.')+'<div class="callout">Ukuran berhasil: kamu bisa mendemokan dan menjelaskan keputusanmu.</div>','Challenge ini kegiatan belajar yang diusulkan, bukan program resmi dengan hadiah atau sertifikat. Bisa menggunakan tool AI yang sudah dimiliki. Masa berlaku paket dihitung sesuai layanan; jadwalkan latihan sebelum membeli.','light')
add('Mulai satu proyek hari ini',label('TokenGateway / Dari belajar ke karya')+head('AI sudah masuk<br>cara orang bekerja.<br><em>Kamu mulai dari mana?</em>')+para('Pilih satu proyek. Beri instruksi yang jelas. Cek hasilnya. Bangun skill-nya.')+'<a class="big-link" href="https://tokengateway.ai.id/pricing" target="_blank" rel="noopener">Lihat paket TokenGateway ↗</a><div class="closing-url">tokengateway.ai.id/pricing</div>','Tutup dengan ajakan konkret. Minta peserta menyebutkan satu proyek yang ingin dibangun. Buka Q&A, lalu gunakan overview untuk kembali ke tabel paket.','cover')
add('Sumber produk dan harga',label('Referensi / dapat diklik')+head('Biar bisa<br><em>dicek bareng.</em>')+'<div class="sources"><a href="https://tokengateway.ai.id/pricing" target="_blank" rel="noopener"><b>01 / Produk & pembayaran</b><span>Pricing TokenGateway. Harga paket, kuota, masa berlaku, dan ringkasan checkout.</span></a><a href="https://claude.com/pricing" target="_blank" rel="noopener"><b>02 / Claude Pro</b><span>US$20 per bulan, penagihan bulanan; harga reguler referensi AS.</span></a><a href="https://help.openai.com/en/articles/6950777-what-is-chatgpt-plus" target="_blank" rel="noopener"><b>03 / ChatGPT Plus</b><span>US$20 per bulan. Penggunaan API terpisah dari langganan aplikasi.</span></a><a href="https://one.google.com/about/plans" target="_blank" rel="noopener"><b>04 / Google AI Pro</b><span>Referensi AS US$19,99 per bulan. Promo, wilayah, dan kelayakan mahasiswa dapat berbeda.</span></a><a href="https://tokengateway.ai.id/api/v1/catalog/packages" target="_blank" rel="noopener"><b>05 / Semua paket</b><span>Katalog publik live, diambil 21 Oktober 2026. 21 paket. Harga dapat berubah.</span></a><a href="https://tokengateway.ai.id/docs" target="_blank" rel="noopener"><b>06 / Setup & batas akses</b><span>Docs dan pricing TokenGateway. Nama model mengikuti katalog gateway; identitas upstream belum diverifikasi independen.</span></a></div>','Materi data dan contoh kode merupakan ilustrasi edukasi. Harga API dan langganan aplikasi bukan perbandingan fitur setara. Tidak ada klaim kemitraan vendor, hasil benchmark, akses Claude, atau jaminan performa. Snapshot live paket tersimpan bersama hasil export.')
